inserted AS (
  INSERT INTO halal_spots (name, description, address, district, latitude, longitude, category, phone, certified, certification_body, featured, status, submitted_by, opening_hours, rating, upvotes)
  SELECT name, description, address, district, latitude, longitude, category, phone, certified, certification_body, false, 'APPROVED', 'excel_import_halal', opening_hours, rating, 0
  FROM source ORDER BY seq
  RETURNING id
),
inserted_seq AS (
  SELECT id, row_number() OVER () AS seq FROM inserted
)
INSERT INTO halal_spot_cuisines (spot_id, cuisine)
SELECT s.id, c
FROM inserted_seq s
JOIN source src ON src.seq = s.seq
CROSS JOIN LATERAL unnest(src.cuisines) AS c
WHERE c IS NOT NULL AND c <> '';
